"""TK-010: district label for every venue of the base from free OSM polygons, no network at pick time.

Stages (resumable, every stage skips what is already on disk):
  python tools/tk010_areas.py bbox     city bounding boxes from venues.ndjson      -> tk010/bbox.json
  python tools/tk010_areas.py fetch    Overpass: district polygons per bbox tile   -> tk010/raw/<city>_<i>.json
  python tools/tk010_areas.py assign   point-in-polygon for all venues              -> tk010/areas.ndjson, stats.json
  python tools/tk010_areas.py all      the three in order, then tk010/DONE
Label rule = pickArea of TK-009 (app/imports/api/places/areaFromCoords.ts): most local field first, statistical
units and the city's own name are not districts, no polygon = no label.
"""
import json, math, os, re, sys, time, unicodedata, urllib.parse, urllib.request
import numpy as np

P = 'C:/verger-data/pilot/'
T = P + 'tk010/'
RAW = T + 'raw2/'   # raw/ (v1) was fetched with `out geom tags`, which drops relation members: not usable
URLS = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter',
        'https://overpass.private.coffee/api/interpreter']
UA = {'User-Agent': 'verger-research/1.0 (1993georgiy@gmail.com)', 'Accept': '*/*'}
FIELDS = ['suburb', 'neighbourhood', 'quarter', 'city_district', 'borough', 'district']
ADMIN_NOISE = re.compile(r'\b(ED|Ward\s+\d+|Community Board\s*\d*|County|Township|Municipio)\b', re.I)
# polygon -> pickArea field: the place tag wins, else Nominatim's admin_level ranks (9 district, 10 suburb, 11 neighbourhood)
ADMIN_FIELD = {'9': 'city_district', '10': 'suburb', '11': 'neighbourhood'}
TILE = 0.3
MAX_TRIES = 8   # per tile; then the tile is skipped (tk010/skipped.txt) and reported, not retried forever
LOG = None

def log(*a):
    global LOG
    if LOG is None:
        os.makedirs(RAW, exist_ok=True); LOG = open(T + 'run.log', 'a', encoding='utf8')
    LOG.write(time.strftime('%H:%M:%S ') + ' '.join(str(x) for x in a) + '\n'); LOG.flush()

def fold(s):
    s = unicodedata.normalize('NFD', s.lower())
    s = ''.join(c for c in s if not 0x300 <= ord(c) <= 0x36f)
    return re.sub(r'[\W_]+', ' ', s).strip()

def slug(city): return re.sub(r'\W+', '_', city.lower()).strip('_')

def cities(): return json.load(open(P + 'cities.json', encoding='utf8'))

def stage_bbox():
    out = T + 'bbox.json'
    if os.path.exists(out): return json.load(open(out))
    pts = {}
    for l in open(P + 'venues.ndjson', encoding='utf8'):
        d = json.loads(l)
        pts.setdefault(d['city'], []).append((d['lat'], d['lng']))
    res = {}
    for c, v in pts.items():
        a = np.array(v)
        lo, hi = np.percentile(a, 0.2, axis=0), np.percentile(a, 99.8, axis=0)
        res[c] = [float(lo[0]) - .01, float(lo[1]) - .01, float(hi[0]) + .01, float(hi[1]) + .01, len(v)]
    json.dump(res, open(out, 'w'), indent=1); log('bbox', len(res), 'cities')
    return res

def tiles(b):
    s, w, n, e = b[:4]
    ny, nx = max(1, math.ceil((n - s) / TILE)), max(1, math.ceil((e - w) / TILE))
    for i in range(ny):
        for j in range(nx):
            yield (s + (n - s) * i / ny, w + (e - w) * j / nx, s + (n - s) * (i + 1) / ny, w + (e - w) * (j + 1) / nx)

QUERY = '''[out:json][timeout:200][bbox:{s:.5f},{w:.5f},{n:.5f},{e:.5f}];
(rel["boundary"="administrative"]["admin_level"~"^(9|10|11)$"][!"ref:TRIRIS"];
 rel["place"~"^(suburb|neighbourhood|quarter|city_district|borough)$"];
 way["place"~"^(suburb|neighbourhood|quarter|city_district|borough)$"];);
out geom;'''

def fetch_order(bb):
    """Cities holding the sample60 gate points first, so the gate can run before the whole download ends."""
    f = P + 'tk008/area60_final.json'
    first = []
    if os.path.exists(f):
        for r in json.load(open(f, encoding='utf8')):
            hit = sorted(((b[2] - b[0]) * (b[3] - b[1]), c) for c, b in bb.items() if b[0] <= r['lat'] <= b[2] and b[1] <= r['lng'] <= b[3])
            if hit and hit[0][1] not in first: first.append(hit[0][1])
    names = [c['city'] for c in cities()]
    return first + [c for c in names if c not in first]

def stage_fetch(shard=0, shards=1):
    """Shard k of n takes every n-th tile and starts on its own mirror, so three processes load three servers."""
    bb = stage_bbox(); g = -1
    for city in fetch_order(bb):
        for i, t in enumerate(tiles(bb[city])):
            g += 1
            path = '%s%s_%d.json' % (RAW, slug(city), i)
            if g % shards != shard or os.path.exists(path): continue
            if os.path.exists(path + '.skip'): continue
            q = QUERY.format(s=t[0], w=t[1], n=t[2], e=t[3]); wait = 20; k = shard; tries = 0
            while True:
                if tries >= MAX_TRIES:
                    open(path + '.skip', 'w').write(time.strftime('%Y-%m-%d %H:%M:%S')); log('tile', city, i, 'SKIPPED after', tries, 'tries'); break
                tries += 1; u = URLS[k % len(URLS)]; k += 1; t0 = time.time()
                try:
                    j = json.load(urllib.request.urlopen(urllib.request.Request(
                        u, data=urllib.parse.urlencode({'data': q}).encode(), headers=UA), timeout=220))
                    json.dump(j['elements'], open(path, 'w', encoding='utf8'), ensure_ascii=False)
                    log('tile', city, i, len(j['elements']), 'objects', round(time.time() - t0, 1), 's', u.split('/')[2])
                    time.sleep(3); break
                except Exception as ex:
                    log('tile', city, i, 'retry in', wait, str(ex)[:80]); time.sleep(wait); wait = min(wait * 2, 300)

def polygons(els):
    """[(field, name, area_deg2, geometry)] from Overpass `out geom` elements, deduped by id."""
    from shapely.geometry import Polygon, LineString, MultiPolygon
    from shapely.ops import polygonize, unary_union
    from shapely import make_valid
    out, seen = [], set()
    for el in els:
        key = (el['type'], el['id'])
        if key in seen: continue
        seen.add(key)
        tg = el.get('tags', {}); name = (tg.get('name') or '').strip()
        field = tg.get('place') if tg.get('place') in FIELDS else ADMIN_FIELD.get(tg.get('admin_level', ''))
        if not name or not field: continue
        try:
            if el['type'] == 'way':
                g = el['geometry']
                if len(g) < 4 or g[0] != g[-1]: continue
                geom = Polygon([(p['lon'], p['lat']) for p in g])
            else:
                lines = {'outer': [], 'inner': []}
                for m in el.get('members', []):
                    if m['type'] == 'way' and m.get('geometry') and len(m['geometry']) > 1:
                        lines['inner' if m.get('role') == 'inner' else 'outer'].append(LineString([(p['lon'], p['lat']) for p in m['geometry']]))
                outer = unary_union(list(polygonize(unary_union(lines['outer'])))) if lines['outer'] else None
                if outer is None or outer.is_empty: continue
                if lines['inner']:
                    outer = outer.difference(unary_union(list(polygonize(unary_union(lines['inner'])))))
                geom = outer
            if not geom.is_valid: geom = make_valid(geom)
            if geom.is_empty: continue
            out.append((field, name, geom.area, geom))
        except Exception as ex:
            log('polygon fail', key, str(ex)[:80])
    return out

def keep(name, city):
    return bool(name) and not ADMIN_NOISE.search(name) and fold(name) not in ('', fold(city))

def city_polygons(city):
    els = []
    for i in range(len(list(tiles(stage_bbox()[city])))):   # a skipped tile leaves a gap: keep going past it
        f = '%s%s_%d.json' % (RAW, slug(city), i)
        if os.path.exists(f): els += json.load(open(f, encoding='utf8'))
    return polygons(els)

def label_points(city, polys, pts):
    """{index in pts: label} for points (lat, lng) that fall in a district polygon of the city."""
    import shapely
    from shapely import STRtree
    res = {}
    if not (polys and pts): return res
    tree = STRtree([p[3] for p in polys])
    pi, gi = tree.query(shapely.points(np.array([[x[1], x[0]] for x in pts])), predicate='intersects')
    per = {}
    for a, b in zip(pi.tolist(), gi.tolist()): per.setdefault(a, []).append(b)
    for a, bs in per.items():
        for f in FIELDS:
            cand = sorted((polys[b] for b in bs if polys[b][0] == f and keep(polys[b][1], city)), key=lambda p: p[2])
            if cand: res[a] = cand[0][1]; break
    return res

def stage_assign():
    by_city = {}
    for l in open(P + 'venues.ndjson', encoding='utf8'):
        d = json.loads(l)
        by_city.setdefault(d['city'], []).append((d['venueId'], d['lat'], d['lng']))
    stats, out = {}, open(T + 'areas.ndjson', 'w', encoding='utf8')
    for c in cities():
        city = c['city']
        polys = city_polygons(city)
        v = by_city.get(city, []); n = len(v); labelled = 0
        for a, label in label_points(city, polys, [(x[1], x[2]) for x in v]).items():
            labelled += 1; out.write(json.dumps({'venueId': v[a][0], 'area': label}, ensure_ascii=False) + '\n')
        stats[city] = {'venues': n, 'labelled': labelled, 'polygons': len(polys), 'share': round(labelled / n, 4) if n else 0}
        log('assign', city, stats[city])
    out.close()
    tot, lab = sum(s['venues'] for s in stats.values()), sum(s['labelled'] for s in stats.values())
    json.dump({'total': {'venues': tot, 'labelled': lab, 'share': round(lab / tot, 4)}, 'cities': stats}, open(T + 'stats.json', 'w'), indent=1, ensure_ascii=False)

if __name__ == '__main__':
    os.makedirs(RAW, exist_ok=True)
    m = sys.argv[1] if len(sys.argv) > 1 else 'all'
    if m == 'all3':  # fetch in 3 processes (one per mirror), then assign, then DONE
        import subprocess
        procs = [subprocess.Popen([sys.executable, '-I', __file__, 'fetch', str(k), '3']) for k in range(3)]
        for p in procs: p.wait()
        m = 'all'
    if m in ('bbox', 'all'): stage_bbox()
    if m in ('fetch', 'all'): stage_fetch(*(int(x) for x in sys.argv[2:4]))
    if m in ('assign', 'all'): stage_assign()
    if m == 'all': open(T + 'DONE', 'w').write(time.strftime('%Y-%m-%d %H:%M:%S'))

