UA = {'User-Agent': 'verger-tk008/1.0 (research)'}
FIELDS = ['suburb', 'neighbourhood', 'quarter', 'city_district', 'borough', 'district', 'city_block', 'village', 'town', 'municipality', 'county']
NOISE = {'district', 'quarter', 'arrondissement', 'ward', 'borough', 'neighborhood', 'neighbourhood', 'area', 'the', 'de', 'di', 'la', 'le', 'el', 'of', 'del', 'des', 'du'}
STOP = {'the', 'bar', 'restaurant', 'le', 'la', 'el', 'de', 'di', 'wine', 'cocktail', 'cocktails', 'and', 'ristorante', 'enoteca', 'club'}


def norm(s):
    s = unicodedata.normalize('NFKD', s.lower())
    s = ''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9 ]', ' ', s).split()


def sig(s):
    return set(norm(s)) - NOISE


def same(a, b):
    A, B = set(norm(a)), set(norm(b))
    if not A or not B:
        return False
    ka, kb = A - STOP, B - STOP
    if ka and kb:
        return len(ka & kb) / len(ka | kb) >= 0.6   # Жаккар: «Fox@Connaught» ≠ «The Connaught Bar»
    return A == B


def get(key, url):
    if key in raw:
        return raw[key]
    r = None
    for _ in range(3):
        try:
            r = json.load(urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=25))
            break
        except Exception:
            time.sleep(4)
    raw[key] = r
    json.dump(raw, open(RAW, 'w', encoding='utf8'), ensure_ascii=False)
    time.sleep(1.1)
    return r


def hav(a, b, c, d):
    p = math.pi / 180
    x = math.sin((c - a) * p / 2) ** 2 + math.cos(a * p) * math.cos(c * p) * math.sin((d - b) * p / 2) ** 2
    return 12742000 * math.asin(math.sqrt(x))


def q(d):
    return urllib.parse.urlencode(d)


def city_of(p):
    # mapsQuery = "<имя> <город>, <страна>"
    m = p['mapsQuery']
    m = m.replace(p['name'], '', 1).strip()
    return m


rows = []
for i, p in enumerate(S):
    la, ln, cc = p['lat'], p['lng'], (p.get('countryCode') or '').lower()
    pid = p['placeId']
    src = 'Overture' if pid.startswith('ov_') else 'Foursquare' if pid.startswith('fsq_') else 'Google/other'
    rv18 = get(f'rv18|{i}', 'https://nominatim.openstreetmap.org/reverse?' + q({'lat': la, 'lon': ln, 'zoom': 18, 'format': 'jsonv2', 'addressdetails': 1}))
    rv14 = get(f'rv14|{i}', 'https://nominatim.openstreetmap.org/reverse?' + q({'lat': la, 'lon': ln, 'zoom': 14, 'format': 'jsonv2', 'addressdetails': 1}))
    names = []
    for r in (rv18, rv14):
