        bb = [float(x) for x in lab['boundingbox']]
        bbox_in = bb[0] <= la <= bb[1] and bb[2] <= ln <= bb[3]
    m2 = bool(lab) and (bbox_in or dist_lab <= 1000)
    border = (not m1) and bool(lab) and not m2 and dist_lab <= 2000
    # (в) положение места
    d = 0.05
    fw = get(f'fw|{i}', 'https://nominatim.openstreetmap.org/search?' + q({'q': p['mapsQuery'], 'format': 'json', 'limit': 5, 'addressdetails': 1, 'viewbox': f'{ln-d},{la+d},{ln+d},{la-d}'}))
    hit = None
    for x in fw or []:
        nm = x.get('name') or x['display_name'].split(',')[0]
        if same(p['name'], nm) and x.get('class') not in ('boundary', 'place', 'highway'):
            hit = {'osm': f"{x['osm_type']}/{x['osm_id']}", 'url': f"https://www.openstreetmap.org/{x['osm_type']}/{x['osm_id']}", 'name': nm,
                   'lat': float(x['lat']), 'lon': float(x['lon']), 'display': x['display_name'], 'dist_m': round(hav(la, ln, float(x['lat']), float(x['lon'])))}
            break
    mc = MC.get(i, {})
    # класс
    match = m1 or m2
    off = bool(hit) and hit['dist_m'] > 300
    if off:
        cls = 'B'
    elif match:
        cls = 'ок'
    elif border:
        cls = 'неясно'
    elif hit:
        cls = 'A'
    else:
        cls = 'A/B?'
    rows.append({'i': i, 'name': p['name'], 'placeId': pid, 'coord_source': src, 'area_shown': area, 'lat': la, 'lng': ln,
                 'point_districts': names, 'match_names': m1, 'label_geocode': {'lat': lab and float(lab['lat']), 'lon': lab and float(lab['lon']), 'dist_m': dist_lab and round(dist_lab), 'bbox_has_point': bbox_in} if lab else None,
                 'match_label_geocode': m2, 'border': border, 'real_place_osm': hit, 'tk007_why': mc.get('why'), 'tk007_url': mc.get('url'), 'class': cls})
    print(i, p['name'][:30], '|', area, '|', names[:3], '|', cls, hit and hit['dist_m'], flush=True)
json.dump(rows, open(D8 + 'area60.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
