"""TK-010 gate, step 1: label the 60 points of sample60 (TK-008) from the downloaded OSM tiles -> tk010/gate_labels.json.
Step 2: node tools/tk010_gate60.mjs (class A by PROTOCOL.md 2.1, hidden share, match with the TK-009 label)."""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import tk010_areas as t

rows = json.load(open('C:/verger-data/pilot/tk008/area60_final.json', encoding='utf8'))
bb = t.stage_bbox()
def city_of(lat, lng):
    hit = [(( b[2] - b[0]) * (b[3] - b[1]), c) for c, b in bb.items() if b[0] <= lat <= b[2] and b[1] <= lng <= b[3]]
    return min(hit)[1] if hit else None

by_city = {}
for r in rows: by_city.setdefault(city_of(r['lat'], r['lng']), []).append(r)
out = {}
for city, rs in by_city.items():
    if city is None:
        for r in rs: out[r['i']] = {'city': None, 'tiles': 0, 'tiles_total': 0, 'label': ''}
        continue
    total = len(list(t.tiles(bb[city])))
    ready = sum(os.path.exists('%s%s_%d.json' % (t.RAW, t.slug(city), i)) for i in range(total))
    labels = t.label_points(city, t.city_polygons(city), [(r['lat'], r['lng']) for r in rs]) if ready else {}
    for k, r in enumerate(rs): out[r['i']] = {'city': city, 'tiles': ready, 'tiles_total': total, 'label': labels.get(k, '')}
json.dump(out, open(t.T + 'gate_labels.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
miss = {(v['city'], v['tiles'], v['tiles_total']) for v in out.values() if v['tiles'] < v['tiles_total']}
print('points', len(out), 'cities', len(by_city), 'incomplete city tiles', sorted(miss, key=str))
// TK-010 gate, step 2 (step 1: python -I tools/tk010_gate60.py -> tk010/gate_labels.json): подпись района места из полигонов OSM
// на 60 местах sample60 (TK-008). Класс A по PROTOCOL.md §2.1, доля скрытых, совпадение с подписью TK-009 (кэш Nominatim raw60.json).
// Запуск: node tools/tk010_gate60.mjs   (итог: C:/verger-data/pilot/tk010/gate_tk010.json)
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';

const D8 = 'C:/verger-data/pilot/tk008/', D10 = 'C:/verger-data/pilot/tk010/';
const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
const exports = {};
const src = readFileSync(new URL('../app/imports/api/places/areaFromCoords.ts', import.meta.url), 'utf8');
runInNewContext(ts.transpileModule(src, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText,
  { exports, console, AbortSignal, Number, Map, Promise, setTimeout, Date });
const { pickArea } = exports;

const NOISE = new Set(['district', 'quarter', 'arrondissement', 'ward', 'borough', 'neighborhood', 'neighbourhood', 'area', 'the', 'de', 'di', 'la', 'le', 'el', 'of', 'del', 'des', 'du']);
const norm = s => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(Boolean);
const sig = s => new Set(norm(s).filter(w => !NOISE.has(w)));
const subset = (a, b) => [...a].every(x => b.has(x));
const matches = (label, names) => { const sa = sig(label); return sa.size > 0 && names.some(n => { const sn = sig(n); return subset(sa, sn) || (sn.size > 0 && subset(sn, sa)); }); };

const raw = JSON.parse(readFileSync(D8 + 'raw60.json', 'utf8'));
const rows = JSON.parse(readFileSync(D8 + 'area60_final.json', 'utf8'));
const lab = JSON.parse(readFileSync(D10 + 'gate_labels.json', 'utf8'));
const out = rows.map(r => {
  const address = raw[`rv14|${r.i}`]?.address;
  const tk009 = pickArea(address, address?.city ?? address?.town ?? address?.village);
  const g = lab[r.i];
  const label = g.label;
  const nowMismatch = label !== '' && !matches(label, r.point_districts);
  return { i: r.i, name: r.name, city: g.city, tiles: `${g.tiles}/${g.tiles_total}`, complete: g.tiles === g.tiles_total && g.tiles_total > 0,
           was: r.area_shown, tk009, now: label, hidden: label === '', now_mismatch: nowMismatch,
           now_A: nowMismatch && !!r.real_place_osm && r.real_place_osm.dist_m <= 300 };
});
const done = out.filter(o => o.complete);
const both = done.filter(o => o.now !== '' && o.tk009 !== '');
const same = both.filter(o => matches(o.now, [o.tk009]) || matches(o.tk009, [o.now]));
const res = {
  n: out.length, cities_complete_points: done.length,
  after: { class_A: done.filter(o => o.now_A).length, label_not_matching_point: done.filter(o => o.now_mismatch).length,
           hidden: done.filter(o => o.hidden).length, shown: done.filter(o => !o.hidden).length, hidden_share: done.length ? +(done.filter(o => o.hidden).length / done.length).toFixed(3) : null },
  vs_tk009: { both_nonempty: both.length, same: same.length, share: both.length ? +(same.length / both.length).toFixed(3) : null },
  incomplete_points: out.filter(o => !o.complete).map(o => `${o.i} ${o.city} ${o.tiles}`),
  labels: out.map(o => `${o.i} [${o.city} ${o.tiles}]: ${o.was} | tk009: ${o.tk009 || '-'} | tk010: ${o.now || '(скрыто)'}${o.now_mismatch ? ' MISMATCH' : ''}`),
};
writeFileSync(D10 + 'gate_tk010.json', JSON.stringify({ res, out }, null, 1));
console.log(JSON.stringify({ ...res, labels: undefined }, null, 1));
console.log(res.labels.join('\n'));
/**
 * District label from the place's own coordinates (TK-009). Off unless
 * AREA_SOURCE=coords, so the card keeps showing the model's `area` exactly as
 * before. TK-008 measured that string against the place: 38 of 60 labels were
 * wrong, 27 of them on a correct point, because the model's district is never
 * checked against anything. With the flag on, the label is whatever the map
 * says about the point, and no data means no label (an empty string is hidden
 * by the card), never the model's guess.
 *
 * Reverse geocoder: OSM Nominatim, free. The public server allows one request
 * a second, so calls are spaced and cached in memory per ~10 m cell; point
 * AREA_REVERSE_URL at your own Nominatim/Photon-compatible server for volume.
 */

export type ReverseAddress = Record<string, string | undefined>;

/** Most local first: a neighbourhood says more than a borough. */
const FIELDS = ['suburb', 'neighbourhood', 'quarter', 'city_district', 'borough', 'district'];

/** Statistical units, not places anyone names: "Wood Quay B ED", "Ward 1986", "Kings County". */
const ADMIN_NOISE = /\b(ED|Ward\s+\d+|Community Board\s*\d*|County|Township|Municipio)\b/i;

const fold = (value: string) =>
  value.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

/** The district to show for a reverse-geocoded address, or '' when it names none. */
export function pickArea(address: ReverseAddress | null | undefined, city?: string): string {
  if (!address) return '';
  const cityKey = city ? fold(city) : '';
  const own = [address.city, address.town, address.village, address.municipality].filter(Boolean).map(value => fold(value!));
  for (const field of FIELDS) {
    const value = address[field]?.trim();
    if (!value || ADMIN_NOISE.test(value)) continue;
    const key = fold(value);
    // "Manhattan" for a Manhattan bar, or the city itself, is not a district.
    if (!key || key === cityKey || own.includes(key)) continue;
    return value;
  }
  return '';
}

type Fetch = (url: string, init: { headers: Record<string, string>; signal: AbortSignal }) => Promise<{ ok: boolean; json(): Promise<unknown> }>;

const DEFAULT_URL = 'https://nominatim.openstreetmap.org/reverse';
const cache = new Map<string, string>();
